1. use std::fmt::Debug;
2. 
3. use chrono::{DateTime, Local, ParseError, TimeZone as _, Utc};
4. use chrono_tz::Tz;
5. use serde::{Deserialize, Serialize};
6. 
7. /// Timezone reference.
8. ///
9. /// This can refer to any valid timezone as defined in the [TZ database][tzdb], or "local" which
10. /// refers to the system local timezone.
11. ///
12. /// [tzdb]: https://en.wikipedia.org/wiki/List_of_tz_database_time_zones
13. #[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Deserialize, Serialize)]
14. #[serde(try_from = "String", into = "String")]
15. pub enum TimeZone {
16.     /// System local timezone.
17.     #[default]
18.     Local,
19. 
20.     /// A named timezone.
21.     ///
22.     /// Must be a valid name in the [TZ database][tzdb].
23.     ///
24.     /// [tzdb]: https://en.wikipedia.org/wiki/List_of_tz_database_time_zones
25.     Named(Tz),
26. }
27. 
28. /// This is a wrapper trait to allow `TimeZone` types to be passed generically.
29. impl TimeZone {
30.     /// Parse a date/time string into `DateTime<Utc>`.
31.     ///
32.     /// # Errors
33.     ///
34.     /// Returns parse errors from the underlying time parsing functions.
35.     pub fn datetime_from_str(&self, s: &str, format: &str) -> Result<DateTime<Utc>, ParseError> {
36.         match self {
37.             Self::Local => Local
38.                 .datetime_from_str(s, format)
39.                 .map(|dt| datetime_to_utc(&dt)),
40.             Self::Named(tz) => tz
41.                 .datetime_from_str(s, format)
42.                 .map(|dt| datetime_to_utc(&dt)),
43.         }
44.     }
45. 
46.     #[must_use]
47.     pub fn parse(s: &str) -> Option<Self> {
48.         match s {
49.             "" | "local" => Some(Self::Local),
50.             _ => s.parse::<Tz>().ok().map(Self::Named),
51.         }
52.     }
53. }
54. 
55. /// Convert a timestamp with a non-UTC time zone into UTC
56. pub(super) fn datetime_to_utc<TZ: chrono::TimeZone>(ts: &DateTime<TZ>) -> DateTime<Utc> {
57.     Utc.timestamp_opt(ts.timestamp(), ts.timestamp_subsec_nanos())
58.         .single()
59.         .expect("invalid timestamp")
60. }
61. 
62. impl From<TimeZone> for String {
63.     fn from(tz: TimeZone) -> Self {
64.         match tz {
65.             TimeZone::Local => "local".to_string(),
66.             TimeZone::Named(tz) => tz.name().to_string(),
67.         }
68.     }
69. }
70. 
71. impl TryFrom<String> for TimeZone {
72.     type Error = String;
73. 
74.     fn try_from(value: String) -> Result<Self, Self::Error> {
75.         match TimeZone::parse(&value) {
76.             Some(tz) => Ok(tz),
77.             None => Err("No such time zone".to_string()),
78.         }
79.     }
